using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class AdditionalMotionInstall {
 public static void Run(){var c=AssetDatabase.LoadAssetAtPath<TrainingApprovedCharacter>("Assets/Shioka/調整Data/Fighter/Awari/Data/AwariCharacter.asset");if(c.backwardWalkAction!=null)throw new Exception("Already migrated; do not overwrite");c.backwardWalkAction=Make("BackwardWalk",new[]{c.backward});c.crouchAction=Make("Crouch",new[]{c.crouch},height:1.1f);c.groundDashAction=Make("GroundDash",new[]{c.dash});c.airDashAction=Make("AirDash",new[]{c.airDash},offset:new Vector2(c.airDashVisualOffset.z,c.airDashVisualOffset.y));c.jumpAction=Make("Jump",new[]{c.jump,c.jumpDescent},TrainingMotionPlayback.JumpPhases);if(c.backstepSequence.Length!=9)throw new Exception("Expected adopted9 backstep poses");c.backstepAction=Make("Backstep",c.backstepSequence,TrainingMotionPlayback.BackstepPhases);c.backward=c.crouch=c.dash=c.airDash=c.jump=c.jumpDescent=c.backstep1=c.backstep2=c.backstep3=null;c.backstepSequence=new Sprite[0];EditorUtility.SetDirty(c);AssetDatabase.SaveAssetIfDirty(c);Debug.Log("ADDITIONAL_MOTION six actions migrated; game-phase timing and inherited body geometry retained");}
 static TrainingMotionAction Make(string name,Sprite[] sprites,TrainingMotionPlayback playback=TrainingMotionPlayback.FrameHolds,Vector2 offset=default,float height=1.55f){string path="Assets/Shioka/調整Data/Fighter/Awari/Move/"+name+"/"+name+".asset";if(AssetDatabase.LoadMainAssetAtPath(path)!=null)throw new Exception("Refuse overwrite "+path);var a=ScriptableObject.CreateInstance<TrainingMotionAction>();a.playback=playback;a.poses=sprites.Select(s=>new TrainingMotionPose{sprite=s,visualOffset=offset,holdFrames=1,hurt=new[]{new TrainingMotionHurt{partId=0,inheritBodyShape=true,center=new Vector2(0,height*.5f),size=new Vector2(.52f,height)}}}).ToArray();if(!a.Validate(out var error))throw new Exception(error);AssetDatabase.CreateAsset(a,path);return a;}
}
